import{_ as i,o,c as l,j as e,a,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/academy/img/anon/prihlaseni.webp",n="/buildary-help-preview/academy/img/anon/registrace.webp",f=JSON.parse('{"title":"Registrace a přihlášení","description":"","frontmatter":{"title":"Registrace a přihlášení","wiki":"cs:firstofall:access"},"headers":[],"relativePath":"firstofall/access.md","filePath":"firstofall/access.md","lastUpdated":1794209661000}'),p={name:"firstofall/access.md"};function c(h,t,m,d,u,v){return o(),l("div",null,[...t[0]||(t[0]=[e("h1",{id:"registrace-a-prihlaseni",tabindex:"-1"},[a("Registrace a přihlášení "),e("a",{class:"header-anchor",href:"#registrace-a-prihlaseni","aria-label":'Permalink to "Registrace a přihlášení"'},"​")],-1),e("p",null,[a("Do Buildary se přihlašujete účtem "),e("strong",null,"First Account"),a(". Stejný účet používáte ve webové i v "),e("a",{href:"/buildary-help-preview/firstofall/mobile"},"mobilní aplikaci"),a(". Účet si založíte sami, zdarma, a hned můžete začít.")],-1),e("p",null,[a("Krok za krokem: "),e("a",{href:"/buildary-help-preview/akademie/prihlaseni"},"Zaregistrovat se a přihlásit"),a(" v Akademii.")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/vvuLgeMZrmQ",title:"Video: Přístup do aplikace",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),r('<h2 id="kde-se-prihlasit" tabindex="-1">Kde se přihlásit <a class="header-anchor" href="#kde-se-prihlasit" aria-label="Permalink to &quot;Kde se přihlásit&quot;">​</a></h2><p>Otevřete <a href="https://buildary.online" target="_blank" rel="noreferrer">www.buildary.online</a> a klikněte na <strong>Přihlášení</strong> vpravo nahoře. Na webu najdete i aktuální informace o aplikaci.</p><figure class="shot" style="--w:640px;"><img src="'+s+'" alt="Přihlašovací okno First Account" loading="lazy"><figcaption>Přihlásit se můžete e-mailem a heslem, Microsoft účtem nebo účtem KROS platformy.</figcaption></figure><h2 id="zalozit-ucet" tabindex="-1">Založit účet <a class="header-anchor" href="#zalozit-ucet" aria-label="Permalink to &quot;Založit účet&quot;">​</a></h2><ol><li>V přihlašovacím okně klikněte na <strong>Vytvořit nový účet</strong>. (Na webu Buildary vede k registraci i tlačítko <strong>Demo na 30 dní zdarma</strong>.)</li><li>Vyplňte e-mail, heslo, jméno a příjmení, potvrďte licenční ujednání a klikněte na <strong>OK</strong>.</li><li>Na e-mail vám přijde zpráva s aktivačním kódem. Účet aktivujte – pak jím můžete pracovat ve všech modulech.</li></ol><figure class="shot" style="--w:640px;"><img src="'+n+'" alt="Registrační formulář First Account" loading="lazy"></figure><p>Pokud se přihlásíte Microsoft účtem a v Buildary ještě účet nemáte, založí se automaticky.</p><h2 id="zustat-prihlaseny" tabindex="-1">Zůstat přihlášený <a class="header-anchor" href="#zustat-prihlaseny" aria-label="Permalink to &quot;Zůstat přihlášený&quot;">​</a></h2><p>Zaškrtněte <strong>Pamatovat přihlášení</strong> a aplikace se vás na přihlášení nebude ptát. Platí to měsíc, pak se přihlaste znovu.</p><h2 id="zapomenute-heslo" tabindex="-1">Zapomenuté heslo <a class="header-anchor" href="#zapomenute-heslo" aria-label="Permalink to &quot;Zapomenuté heslo&quot;">​</a></h2><p>V přihlašovacím okně klikněte na <strong>Zapomněl jsem heslo</strong>, zadejte e-mail a potvrďte. Dál postupujte podle pokynů v e-mailu.</p><p>Pokud se přihlašujete Microsoft účtem, heslo v Buildary neobnovujete – spravuje ho Microsoft.</p><h2 id="prihlaseni-microsoft-uctem" tabindex="-1">Přihlášení Microsoft účtem <a class="header-anchor" href="#prihlaseni-microsoft-uctem" aria-label="Permalink to &quot;Přihlášení Microsoft účtem&quot;">​</a></h2><p>Klikněte na <strong>Přihlásit se pomocí Microsoft účtu</strong> a přihlaste se k Microsoftu. E-mail ani heslo do Buildary nevyplňujete. Při prvním přihlášení povolte aplikaci Buildary přístup ke jménu a e-mailu z Microsoft účtu – bez toho účty nejde spárovat.</p><div class="warning custom-block"><p class="custom-block-title">Pak už jen přes Microsoft</p><p>Jakmile se poprvé přihlásíte Microsoft účtem, přihlášení e-mailem a heslem se vypne – na webu i v mobilu. Od té doby se přihlašujte jen tlačítkem <strong>Přihlásit se pomocí Microsoft účtu</strong>, i když jste účet původně založili registrací.</p></div><h2 id="prvni-prihlaseni" tabindex="-1">První přihlášení <a class="header-anchor" href="#prvni-prihlaseni" aria-label="Permalink to &quot;První přihlášení&quot;">​</a></h2><p>Po prvním přihlášení vám aplikace nabídne vytvoření <strong>Demo stavby</strong> s ukázkovými daty – viz <a href="/buildary-help-preview/firstofall/#jak-zacit">Co je Buildary</a>. Pak se otevře Seznam staveb; co je kde na obrazovce, popisuje <a href="/buildary-help-preview/firstofall/description">Orientace v aplikaci</a>.</p><p>Když se přihlášení nedaří, podívejte se na <a href="/buildary-help-preview/firstofall/loginproblems">Problémy s přihlášením</a>.</p>',18)])])}const g=i(p,[["render",c]]);export{f as __pageData,g as default};
